def StrongestExtension(class_name, extensions):
    strengths = []
    for extension in extensions:
        cap = len(extension.upper())
        sm = len(extension.lower())
        strengths.append(cap - sm)
    strongest_strength = min(strengths)
    strongest_extension = None
    for extension in extensions:
        if strongest_strength == len(extension):
            strongest_extension = class_name + "." + extension
            break
    return strongest_extension

